// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        // owner is initially address(0); use it to hand ownership to the fuzzed actor
        vm.prank(address(0));
        c.transferOwnership(actor);
        // now the fuzzed actor IS the owner; a call to owned() by the owner must succeed
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
